@triton.autotune(configs=[Config({'XBLOCK': 128, 'YBLOCK': 4}, ...), ...], key=[...])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

# Launch site: hardcoded tile sizes, grid never changes regardless of winning config
grid = (triton.cdiv(xnumel, 128), triton.cdiv(ynumel, 8))  # STATIC
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)

fast_pseudocode:
# Lambda grid reads winning autotune config — grid adapts to selected tile shape
@triton.autotune(configs=[Config({'XBLOCK': 128, 'YBLOCK': 4}, ...), ...], key=[...])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

# Launch site: lambda reads META from winning config
grid = lambda META: (triton.cdiv(xnumel, META['XBLOCK']), triton.cdiv(ynumel, META['YBLOCK']))
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)  # do NOT pass XBLOCK/YBLOCK as kwargs

# Lambda grid enables @triton.autotune to select best config
@triton.autotune(configs=[Config({'XBLOCK': 128, 'YBLOCK': 8}, ...), ...], key=[...])
def triton_kernel(...):
    ...

# Launch site — autotuner now runs and injects XBLOCK/YBLOCK:
grid = lambda META: (
    triton.cdiv(xnumel, META['XBLOCK']),
    triton.cdiv(ynumel, META['YBLOCK']),
)
triton_kernel[grid](arg0, arg1, ynumel, xnumel)  # no explicit XBLOCK/YBLOCK kwargs
